('12000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','ops-b@example.com','',now(),'{}','{}',now(),now()),
('12000000-0000-4000-8000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','ops-staff@example.com','',now(),'{}','{}',now(),now());
insert into organizations(id,name,slug) values('22000000-0000-4000-8000-000000000001','Ops A','ops-a'),('22000000-0000-4000-8000-000000000002','Ops B','ops-b');
insert into organization_memberships(organization_id,user_id,role) values
('22000000-0000-4000-8000-000000000001','12000000-0000-4000-8000-000000000001','owner'),('22000000-0000-4000-8000-000000000001','12000000-0000-4000-8000-000000000003','advisor'),('22000000-0000-4000-8000-000000000002','12000000-0000-4000-8000-000000000002','owner');
insert into branches(id,organization_id,name,timezone,is_primary) values('42000000-0000-4000-8000-000000000001','22000000-0000-4000-8000-000000000001','Ops Branch A','Asia/Manila',true),('42000000-0000-4000-8000-000000000002','22000000-0000-4000-8000-000000000002','Ops Branch B','Asia/Manila',true);
insert into customers(id,organization_id,full_name) values('52000000-0000-4000-8000-000000000001','22000000-0000-4000-8000-000000000001','Ops Customer A'),('52000000-0000-4000-8000-000000000002','22000000-0000-4000-8000-000000000002','Ops Customer B');
insert into vehicles(id,organization_id,customer_id,make,model,vehicle_type) values('62000000-0000-4000-8000-000000000001','22000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000001','Toyota','Fortuner','SUV'),('62000000-0000-4000-8000-000000000002','22000000-0000-4000-8000-000000000002','52000000-0000-4000-8000-000000000002','Honda','City','Sedan');
insert into service_categories(id,organization_id,name) values('72000000-0000-4000-8000-000000000001','22000000-0000-4000-8000-000000000001','Wash'),('72000000-0000-4000-8000-000000000002','22000000-0000-4000-8000-000000000002','Wash');
insert into services(id,organization_id,category_id,name,duration_minutes,base_price_centavos) values('82000000-0000-4000-8000-000000000001','22000000-0000-4000-8000-000000000001','72000000-0000-4000-8000-000000000001','Basic Wash A',45,30000),('82000000-0000-4000-8000-000000000002','22000000-0000-4000-8000-000000000002','72000000-0000-4000-8000-000000000002','Basic Wash B',60,40000),('82000000-0000-4000-8000-000000000003','22000000-0000-4000-8000-000000000001','72000000-0000-4000-8000-000000000001','Interior A',90,100000);
insert into service_prices(organization_id,service_id,branch_id,vehicle_class,price_centavos) values
('22000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001',null,'suv',35000),('22000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','42000000-0000-4000-8000-000000000001',null,32500),('22000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','42000000-0000-4000-8000-000000000001','suv',37500);

select plan(48);
select has_table('public','service_prices','service prices exists'); select has_table('public','service_branch_availability','branch availability exists'); select has_table('public','queue_entries','queue exists'); select has_function('public','resolve_service_price',array['uuid','uuid','text'],'price resolver exists');
select has_view('public','appointment_directory','appointment search projection exists'); select has_view('public','queue_directory','queue search projection exists');
select is(resolve_service_price('82000000-0000-4000-8000-000000000003','42000000-0000-4000-8000-000000000001','suv'),100000::bigint,'base price fallback');
select is(resolve_service_price('82000000-0000-4000-8000-000000000001','42000000-0000-4000-8000-000000000002','suv'),35000::bigint,'organization vehicle price');
select is(resolve_service_price('82000000-0000-4000-8000-000000000001','42000000-0000-4000-8000-000000000001','sedan'),32500::bigint,'branch base override');
select is(resolve_service_price('82000000-0000-4000-8000-000000000001','42000000-0000-4000-8000-000000000001','suv'),37500::bigint,'branch vehicle price wins');
select throws_ok($$insert into service_prices(organization_id,service_id,branch_id,price_centavos) values('22000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','42000000-0000-4000-8000-000000000002',1)$$,'P0001','Service configuration organization mismatch','cross-tenant branch price denied');
select throws_ok($$insert into service_branch_availability(organization_id,service_id,branch_id) values('22000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','42000000-0000-4000-8000-000000000002')$$,'P0001','Service configuration organization mismatch','cross-tenant availability denied');
set local role anon; set local "request.jwt.claims"='{"role":"anon"}';
select throws_ok($$select * from service_prices$$,'42501',null,'anon cannot read prices'); select throws_ok($$select * from queue_entries$$,'42501',null,'anon cannot read queue');
select throws_ok($$select * from appointment_directory$$,'42501',null,'anon cannot search appointments'); select throws_ok($$select * from queue_directory$$,'42501',null,'anon cannot search queue');
reset role; set local role authenticated; set local "request.jwt.claims"='{"sub":"12000000-0000-4000-8000-000000000001","role":"authenticated"}';
select is((select count(*) from services)::bigint,2::bigint,'Owner A sees own services'); select is((select count(*) from appointments)::bigint,0::bigint,'Owner A sees no foreign appointments'); select is((select count(*) from queue_entries)::bigint,0::bigint,'Owner A sees no foreign queue'); select is((select count(*) from service_prices)::bigint,3::bigint,'Owner A sees own prices');
select is((select count(*) from services where id='82000000-0000-4000-8000-000000000002')::bigint,0::bigint,'Owner A cannot read Service B'); select is((select count(*) from appointments where organization_id='22000000-0000-4000-8000-000000000002')::bigint,0::bigint,'Owner A cannot read Appointment B');
select is_empty($$update services set name='attack' where id='82000000-0000-4000-8000-000000000002' returning 1$$,'Owner A cannot update Service B'); select is_empty($$update appointments set customer_note='attack' where organization_id='22000000-0000-4000-8000-000000000002' returning 1$$,'Owner A cannot update Appointment B');
select lives_ok($$select save_appointment(null,'42000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000001','62000000-0000-4000-8000-000000000001',array['82000000-0000-4000-8000-000000000001'::uuid,'82000000-0000-4000-8000-000000000003'::uuid],now()+interval '1 day')$$,'trusted appointment creation works');
select is((select count(*) from appointment_services)::bigint,2::bigint,'multiple service snapshots created'); select is((select unit_price_centavos from appointment_services where service_id='82000000-0000-4000-8000-000000000001'),37500::bigint,'vehicle/branch snapshot price correct'); select is((select sum(duration_minutes) from appointment_services)::bigint,135::bigint,'snapshot durations correct'); select is((select expected_total_centavos from appointments limit 1),137500::bigint,'appointment total correct'); select ok((select ends_at=starts_at+interval '135 minutes' from appointments limit 1),'estimated end correct');
update appointments set expected_total_centavos=1 where true; select is((select expected_total_centavos from appointments limit 1),137500::bigint,'client total manipulation ignored');
select lives_ok($$select transition_appointment((select id from appointments limit 1),'confirm')$$,'confirm transition works'); select is((select status::text from appointments limit 1),'confirmed','appointment confirmed'); select lives_ok($$select transition_appointment((select id from appointments limit 1),'arrive')$$,'arrival transition works'); select is((select status::text from appointments limit 1),'checked_in','appointment arrived');
select lives_ok($$select enqueue_appointment((select id from appointments limit 1))$$,'appointment enters queue'); select is((select queue_number from queue_entries limit 1),1,'first queue number is atomic counter 1'); select throws_ok($$select enqueue_appointment((select id from appointments limit 1))$$,'P0001','Appointment must be confirmed or arrived','duplicate enqueue rejected');
select lives_ok($$select create_walk_in('42000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000001','62000000-0000-4000-8000-000000000001',array['82000000-0000-4000-8000-000000000001'::uuid],'walk in')$$,'walk-in created atomically'); select is((select count(*) from queue_entries where source='walk_in')::bigint,1::bigint,'walk-in queue entry created'); select is((select max(queue_number) from queue_entries),2,'queue number increments safely');
select throws_ok($$select save_appointment(null,'42000000-0000-4000-8000-000000000002','52000000-0000-4000-8000-000000000001','62000000-0000-4000-8000-000000000001',array['82000000-0000-4000-8000-000000000001'::uuid],now()+interval '1 day')$$,'42501','Access denied','Org A cannot book Branch B');
select throws_ok($$select save_appointment(null,'42000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000002','62000000-0000-4000-8000-000000000001',array['82000000-0000-4000-8000-000000000001'::uuid],now()+interval '1 day')$$,'P0001','Appointment organization mismatch','Org A cannot book Customer B');
select throws_ok($$select save_appointment(null,'42000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000001','62000000-0000-4000-8000-000000000002',array['82000000-0000-4000-8000-000000000001'::uuid],now()+interval '1 day')$$,'P0001','Appointment organization mismatch','Org A cannot book Vehicle B');
select throws_ok($$insert into appointment_services(appointment_id,service_id,service_name_snapshot,unit_price_centavos,duration_minutes) values((select id from appointments limit 1),'82000000-0000-4000-8000-000000000002','attack',1,1)$$,'P0001','Appointment/service organization mismatch','Org A appointment cannot select Service B');
reset role; select throws_ok($$insert into queue_entries(organization_id,branch_id,customer_id,vehicle_id,source,queue_date,queue_number,estimated_duration_minutes) values('22000000-0000-4000-8000-000000000001','42000000-0000-4000-8000-000000000002','52000000-0000-4000-8000-000000000001','62000000-0000-4000-8000-000000000001','walk_in',current_date,99,10)$$,'P0001','Queue organization mismatch','cross-tenant queue branch rejected');
set local role authenticated; set local "request.jwt.claims"='{"sub":"12000000-0000-4000-8000-000000000003","role":"authenticated"}'; select is_empty($$update services set name='blocked' where id='82000000-0000-4000-8000-000000000001' returning 1$$,'advisor cannot modify services'); select lives_ok($$select save_appointment(null,'42000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000001','62000000-0000-4000-8000-000000000001',array['82000000-0000-4000-8000-000000000001'::uuid],now()+interval '2 days')$$,'advisor can create appointment');
select * from finish(); rollback;
